import bruzem

def _extract(value):
    """Extract the numeric component from the result of bruzem.find."""
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, tuple):
        # Assume the numeric part is the second element if present
        return value[1] if len(value) > 1 else value[0]
    if hasattr(value, "value"):
        return getattr(value, "value")
    return value  # fallback

# Retrieve and extract the stored values
sigma_val = _extract(bruzem.find('sigma'))
kappa_val = _extract(bruzem.find('kappa'))

# Build the required dictionary
